#!/usr/bin/env node
'use strict';
// Validates a daily edition file. Usage: node scripts/validate.js data/2026-09-11.json [--check-links]
// Exits non-zero on any schema error, or (with --check-links) on any link that returns 404/410.
// Other HTTP failures (403, 429, timeouts — common for bot-blocking sites) are reported as warnings.
// The week in review has its own file and validator: scripts/validate-week.js.

const fs = require('fs');
const path = require('path');
const { makeReporter, checkItem, checkLinks } = require('./validate-lib.js');

const SECTIONS = new Set([
  'Frontier models & labs', 'Research & papers', 'Security, misuse & threat intelligence',
  'Military, defense & geopolitics', 'Health, science & medicine', 'Policy, regulation & law',
  'Compute, chips & infrastructure', 'Deployment & impact',
]);

const file = process.argv[2];
const doLinks = process.argv.includes('--check-links');
if (!file) { console.error('usage: validate.js data/YYYY-MM-DD.json [--check-links]'); process.exit(2); }

const rep = makeReporter();
const { err, warn } = rep;

let ed;
try { ed = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { console.error(`Cannot parse ${file}: ${e.message}`); process.exit(1); }

const fname = path.basename(file, '.json');
if (!/^\d{4}-\d{2}-\d{2}$/.test(fname)) err(`filename must be YYYY-MM-DD.json (got ${fname})`);
if (ed.date !== fname) err(`"date" (${ed.date}) must match filename (${fname})`);
if (ed.edition !== 'daily') err(`"edition" must be "daily" (the week in review is a separate data/DATE.week.json)`);
if (ed.week_in_review) err(`"week_in_review" no longer belongs in a daily edition — it is its own file, data/DATE.week.json`);
if (!ed.generated_at || isNaN(Date.parse(ed.generated_at))) err(`"generated_at" must be an ISO timestamp`);
const summaryText = Array.isArray(ed.summary) ? ed.summary.join(' ') : String(ed.summary || '');
if (summaryText.trim().length < 200) err(`"summary" is too short (${summaryText.trim().length} chars; want a real paragraph or two)`);
if (!Array.isArray(ed.sections) || !ed.sections.length) err(`"sections" must be a non-empty array`);

const ctx = { err, warn, urls: new Map(), headlines: new Set() };
let itemTotal = 0;
for (const [si, sec] of (ed.sections || []).entries()) {
  const where = `sections[${si}] "${sec.name}"`;
  if (!SECTIONS.has(sec.name)) err(`${where}: unknown section name. Allowed: ${[...SECTIONS].join(' | ')}`);
  if (!Array.isArray(sec.items) || !sec.items.length) err(`${where}: has no items (drop empty sections)`);
  for (const [ii, it] of (sec.items || []).entries()) { itemTotal++; checkItem(it, `${where} item[${ii}]`, ctx); }
}
if (itemTotal < 5) warn(`only ${itemTotal} items — a normal day has 10–25`);

(async () => {
  if (doLinks && !rep.errors.length) await checkLinks(ctx.urls, rep);
  rep.report(file, `${itemTotal} items, ${ctx.urls.size} links`);
})();

'use strict';
// Shared checks for the three validators (edition, week in review, podcast script).
// Keep network code here and out of lib.js, which build.js loads at build time.

const fs = require('fs');
const path = require('path');
const IMPACTS = new Set(['beneficial', 'harmful', 'mixed', 'neutral']);
const FLAGS = new Set(['company-claim', 'single-source', 'preprint', 'update']);
const SLUG_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const isHttp = (u) => /^https?:\/\/\S+$/.test(u || '');
const isHomepage = (u) => /^https?:\/\/[^/]+\/?$/.test(u);
const isPlaceholder = (u) => /example\.com|\.\.\./.test(u);

// Speculation and hype — never allowed in anything we publish or voice.
const BANNED = ['i think', 'i bet', 'i guess', 'probably', 'could mean', 'might mean', 'imagine if', 'game-changer', 'game changer', 'huge', 'massive', 'insane', 'crazy', 'wild', 'mind-blowing', 'mind blowing', 'scary', 'terrifying', 'exciting', 'incredible', 'unbelievable', 'revolutionary', 'blew my mind', 'jaw-dropping'];
const WARN_WORDS = ['interesting', 'fascinating'];
// Editorial opinion — the week in review states facts, relationships and open questions; it never takes a view.
const OPINION_ERROR = [...BANNED, 'we believe', 'we think', 'we expect', 'we suspect', 'in our view', 'in our opinion', 'our take', 'our read', 'clearly', 'obviously', 'undoubtedly', 'no doubt', 'it is likely', "it's likely", 'is likely to', 'are likely to', 'in all likelihood', 'all but certain', 'inevitable', 'inevitably', 'it seems', 'seems to', 'appears to be', 'arguably', 'the real story', 'the takeaway', 'bottom line', 'make no mistake', 'read between the lines', 'could signal', 'may signal', 'game-changing'];
const OPINION_WARN = ['likely', 'suggests that', 'suggest that', 'signals that', 'signal that', 'should', 'must', 'could', 'might', 'notably', 'importantly', 'interestingly', 'worrying', 'alarming', 'concerning', 'striking', 'remarkable', 'landmark', 'watershed', 'unprecedented', 'historic'];
// A sentence that asserts a cause must attribute it to someone who said so.
const CAUSAL_RE = /\b(because|led to|leads to|caused|causes|driven by|in response to|as a result|resulted in|due to|prompted|triggered|in reaction to|therefore|consequently|explains why|is why|to counter|retaliat\w*)\b/i;
const ATTRIBUTION_RE = /\b(said|says|wrote|writes|told|according to|reported|reports|argued|argues|stated|states|attributed|attributes|cited|cites|citing|described|describes|filing|announced|testified)\b/i;

const NUM_RE = /\d[\d,]*(?:\.\d+)?/g;
const normNum = (n) => n.replace(/,/g, '').replace(/\.0+$/, '');
const digitsOf = (text) => new Set((String(text).replace(/,/g, '').match(/\d+(?:\.\d+)?/g) || []).map(normNum));

const escapeRe = (s) => s.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
// Phrases from `list` found in `text` (word-bounded, case-insensitive).
const bannedHits = (text, list) => list.filter((w) => new RegExp(`\\b${escapeRe(w)}\\b`, 'i').test(text));
// Quoted spans are what a source said, not us — drop them before scanning for opinion or causation.
const stripQuotes = (text) => String(text).replace(/"[^"]*"|“[^”]*”|‘[^’]*’/g, ' ');
const sentences = (text) => String(text).split(/(?<=[.!?])\s+(?=[A-Z"“(])/).map((s) => s.trim()).filter(Boolean);

function makeReporter() {
  const errors = [], warnings = [];
  return {
    errors, warnings,
    err: (m) => errors.push(m),
    warn: (m) => warnings.push(m),
    report(file, summary) {
      for (const w of warnings) console.log(`WARN  ${w}`);
      for (const e of errors) console.log(`ERROR ${e}`);
      console.log(`${file}: ${summary} — ${errors.length} error(s), ${warnings.length} warning(s)`);
      process.exit(errors.length ? 1 : 0);
    },
  };
}

// Ids of the storylines an item may be filed under (storylines/*.json), with their status.
function storylineIds() {
  const dir = path.join(__dirname, '..', 'storylines');
  const out = new Map();
  if (!fs.existsSync(dir)) return out;
  for (const f of fs.readdirSync(dir)) if (f.endsWith('.json')) { try { out.set(f.slice(0, -5), JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')).status || 'live'); } catch { /* validate-storyline reports it */ } }
  return out;
}
const STORYLINES = storylineIds();

// The daily item shape. ctx = { err, warn, urls: Map(url -> where), headlines: Set }.
function checkItem(it, where, ctx) {
  const { err, warn, urls, headlines } = ctx;
  if (!it.headline || it.headline.trim().length < 15) err(`${where}: headline missing or too short`);
  if (it.headline && headlines.has(it.headline.trim().toLowerCase())) err(`${where}: duplicate headline "${it.headline}"`);
  headlines.add((it.headline || '').trim().toLowerCase());
  if (!Array.isArray(it.sources) || !it.sources.length) err(`${where}: needs at least one source`);
  for (const [i, s] of (it.sources || []).entries()) {
    if (!s || !isHttp(s.url)) err(`${where}: source[${i}] has no valid http(s) url`);
    else {
      if (isHomepage(s.url)) err(`${where}: source[${i}] is a homepage (${s.url}) — link the specific article, paper or document`);
      if (isPlaceholder(s.url)) err(`${where}: source[${i}] looks like a placeholder url`);
      if (!urls.has(s.url)) urls.set(s.url, where);
    }
    if (!s.name) warn(`${where}: source[${i}] has no "name" (will fall back to hostname)`);
  }
  if (!Array.isArray(it.bullets) || !it.bullets.length) err(`${where}: needs at least one bullet`);
  for (const [i, b] of (it.bullets || []).entries()) if (typeof b !== 'string' || b.trim().length < 20) err(`${where}: bullet[${i}] too short`);
  if (!Array.isArray(it.topics) || !it.topics.length) err(`${where}: needs at least one topic slug`);
  for (const t of it.topics || []) if (!SLUG_RE.test(t)) err(`${where}: topic "${t}" must be a lowercase-hyphen slug`);
  if (it.impact && !IMPACTS.has(it.impact)) err(`${where}: impact must be one of ${[...IMPACTS].join('|')}`);
  for (const f of it.flags || []) if (!FLAGS.has(f)) err(`${where}: flag "${f}" must be one of ${[...FLAGS].join('|')}`);
  // Storylines: only existing, open ones. The daily never creates a storyline; the weekly does.
  if (it.storylines !== undefined && !Array.isArray(it.storylines)) err(`${where}: "storylines" must be an array of ids`);
  for (const id of it.storylines || []) {
    if (!STORYLINES.has(id)) err(`${where}: storyline "${id}" does not exist — use an id from \`node scripts/build.js --storylines\`, or none`);
    else if (STORYLINES.get(id) === 'resolved') err(`${where}: storyline "${id}" is resolved — file the item elsewhere or leave it untagged`);
  }
  if ((it.storylines || []).length > 3) warn(`${where}: filed under ${it.storylines.length} storylines — usually one, at most two`);
}

async function checkUrl(url) {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), 15000);
  const headers = { 'user-agent': 'Mozilla/5.0 (compatible; ai-edge-briefing-linkcheck/1.0)', accept: 'text/html,application/xhtml+xml,*/*' };
  try {
    let r = await fetch(url, { method: 'HEAD', redirect: 'follow', headers, signal: ctl.signal });
    if (r.status === 405 || r.status === 403 || r.status === 400 || r.status === 501) r = await fetch(url, { method: 'GET', redirect: 'follow', headers, signal: ctl.signal });
    return { status: r.status };
  } catch (e) { return { error: e.name === 'AbortError' ? 'timeout' : e.message }; }
  finally { clearTimeout(timer); }
}

// Bot-blocked or unreachable links can be confirmed through headless Chrome at the edge (Cloudflare Browser
// Rendering) when CLOUDFLARE_BROWSER_TOKEN + CLOUDFLARE_ACCOUNT_ID exist. Sequential (the free tier allows one browser).
(function loadDotenv(file) { try { for (const line of fs.readFileSync(file, 'utf8').split('\n')) { const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/); if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^['"]|['"]$/g, ''); } } catch { /* none */ } })(path.join(__dirname, '..', 'stats', '.env'));
const canRender = () => !!(process.env.CLOUDFLARE_BROWSER_TOKEN && process.env.CLOUDFLARE_ACCOUNT_ID);
async function renderCheck(url) {
  const res = await fetch(`https://api.cloudflare.com/client/v4/accounts/${process.env.CLOUDFLARE_ACCOUNT_ID}/browser-rendering/content`, { method: 'POST', headers: { authorization: `Bearer ${process.env.CLOUDFLARE_BROWSER_TOKEN}`, 'content-type': 'application/json' }, body: JSON.stringify({ url, rejectResourceTypes: ['image', 'media', 'font'], gotoOptions: { waitUntil: 'domcontentloaded', timeout: 20000 } }) });
  const j = await res.json().catch(() => ({}));
  if (!res.ok || !j.success) return { error: (j.errors || []).map((e) => e.message).join('; ') || `HTTP ${res.status}` };
  const html = String(j.result || '');
  const title = (html.match(/<title[^>]*>([^<]*)/i) || [])[1] || '';
  if (/\b(404|not found|page doesn.t exist|page not found)\b/i.test(title)) return { status: 404, title };
  return { status: 200, chars: html.length, title };
}

// 404/410 is an error (dead link); anything else that fails is a warning to verify by hand — or, with Browser
// Rendering configured, a second check through a real browser that upgrades the warning to pass/fail.
async function checkLinks(urls, { err, warn }) {
  const list = [...urls.entries()];
  console.log(`Checking ${list.length} links…`);
  const results = await Promise.all(list.map(async ([url, where]) => [url, where, await checkUrl(url)]));
  const rendered = [];
  for (const [url, where, r] of results) {
    if (r.error) warn(`${where}: ${url} — ${r.error} (could not verify; verify manually via WebFetch)`);
    else if (r.status === 404 || r.status === 410) err(`${where}: ${url} — HTTP ${r.status} (dead link: fix or remove)`);
    else if (r.status >= 400) {
      if (!canRender()) warn(`${where}: ${url} — HTTP ${r.status} (bot-blocked? verify manually via WebFetch)`);
      else rendered.push([url, where, r.status]);
    }
  }
  if (rendered.length) {
    console.log(`Re-checking ${rendered.length} blocked link(s) through headless Chrome…`);
    for (const [url, where, status] of rendered) {
      const c = await renderCheck(url);
      if (c.error) warn(`${where}: ${url} — HTTP ${status}, and the browser check failed (${c.error}); verify manually via WebFetch`);
      else if (c.status === 404) err(`${where}: ${url} — HTTP ${status}, and the browser sees a not-found page ("${c.title}"): fix or remove`);
      else console.log(`ok    ${where}: ${url} — HTTP ${status} to a plain request but opens in a browser${c.title ? ` ("${c.title.slice(0, 60)}")` : ''}`);
    }
  }
}

module.exports = { STORYLINES, IMPACTS, FLAGS, SLUG_RE, isHttp, isHomepage, isPlaceholder, BANNED, WARN_WORDS, OPINION_ERROR, OPINION_WARN, CAUSAL_RE, ATTRIBUTION_RE, NUM_RE, normNum, digitsOf, bannedHits, stripQuotes, sentences, makeReporter, checkItem, checkUrl, checkLinks };

#!/usr/bin/env node
'use strict';
// Validates a podcast dialogue script against its edition. These are the LOCKS that make a two-host
// conversation acceptable: nothing in the script may go beyond what the edition says.
// Usage: node scripts/validate-script.js data/2026-09-11.script.json
// Exit 0 = every lock holds. Exit 1 = at least one ERROR (the Action then ships the code-generated narration instead).

const fs = require('fs');
const path = require('path');
const { longDate, spokenDate, ordinal, dateObj, PODCAST } = require('./lib.js');
const { BANNED, WARN_WORDS, NUM_RE, normNum, digitsOf, bannedHits } = require('./validate-lib.js');

const VOICES = new Set(['alloy', 'ash', 'ballad', 'coral', 'echo', 'fable', 'nova', 'onyx', 'sage', 'shimmer', 'verse', 'marin', 'cedar']);
const BLOCK_TYPES = new Set(['intro', 'item', 'transition', 'outro']);
const CAVEAT_PHRASES = {
  'company-claim': ['company claim', 'company says', 'company-reported', 'not independently verified', "hasn't been independently verified", 'has not been independently verified', 'their own numbers', 'its own numbers'],
  'single-source': ['single source', 'only one outlet', 'one outlet', 'only source', 'no one else has confirmed', 'nobody else has confirmed'],
  preprint: ['preprint', 'not peer reviewed', "hasn't been peer reviewed", 'not been peer reviewed', 'pre-print'],
  update: ['update', 'follow-up', 'follow up', 'we covered', 'covered before', 'earlier edition'],
};
const BULLET_CAVEAT_TRIGGERS = ['unverified', 'not independently', 'did not say', 'does not say', 'could not confirm', "couldn't confirm", 'caveat', 'has not confirmed', 'not yet confirmed'];
const SCRIPT_CAVEAT_WORDS = ['unverified', 'not verified', 'does not say', 'not independently verified', 'not an independent', "hasn't verified", "hasn't confirmed", 'has not confirmed', "haven't confirmed", 'caveat', 'not independently', "didn't say", 'did not say', "doesn't say", "couldn't confirm", 'could not confirm', 'only ', 'not yet'];
const NUMBER_WORDS = /\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|a couple of|a few|several|dozens of|hundreds of|thousands of|millions of|billions of)\s+(hundred|thousand|million|billion|trillion|percent|per cent)\b/i;

const file = process.argv[2];
if (!file) { console.error('usage: validate-script.js data/YYYY-MM-DD.script.json'); process.exit(2); }
const errors = [], warnings = [];
const err = (m) => errors.push(m);
const warn = (m) => warnings.push(m);

let sc;
try { sc = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { console.log(`ERROR cannot parse ${file}: ${e.message}`); process.exit(1); }
const date = path.basename(file).slice(0, 10);
const edPath = path.join(path.dirname(file), `${date}.json`);
if (!fs.existsSync(edPath)) { console.log(`ERROR no edition file ${edPath}`); process.exit(1); }
const ed = JSON.parse(fs.readFileSync(edPath, 'utf8'));
ed.sections = (ed.sections || []).filter((s) => s.items && s.items.length);

// ---------- schema ----------
if (sc.date !== date) err(`"date" (${sc.date}) must be ${date}`);
if (sc.format !== 'dialogue') err(`"format" must be "dialogue"`);
const hosts = sc.hosts || {};
const hostKeys = Object.keys(hosts);
if (hostKeys.length !== 2) err(`exactly two hosts required (got ${hostKeys.length})`);
for (const k of hostKeys) {
  if (!hosts[k].name) err(`host ${k} needs a name`);
  if (!VOICES.has(hosts[k].voice)) err(`host ${k} voice "${hosts[k].voice}" is not a supported voice (${[...VOICES].join(', ')})`);
}
if (hostKeys.length === 2 && hosts[hostKeys[0]].voice === hosts[hostKeys[1]].voice) err(`the two hosts must use different voices`);
if (!Array.isArray(sc.blocks) || !sc.blocks.length) err(`"blocks" must be a non-empty array`);

// ---------- edition lookups ----------
const itemByHeadline = new Map();
for (const sec of ed.sections) for (const it of sec.items) itemByHeadline.set(it.headline, { item: it, section: sec.name });
const itemText = (it) => [it.headline, ...(it.bullets || [])].join(' ');
const summaryText = Array.isArray(ed.summary) ? ed.summary.join(' ') : String(ed.summary || '');
const summaryDigits = digitsOf(summaryText);
const dateDigits = new Set([...digitsOf(`${longDate(date)} ${date}`), '24']); // "the last 24 hours" is always allowed

// ---------- walk blocks ----------
const seenItems = new Set();
const sectionsCovered = new Set();
let words = 0, lineCount = 0, itemBlocks = 0, introSeen = false, outroSeen = false;
const warnWordCount = {};
let prevHost = null, run = 0;

(sc.blocks || []).forEach((b, bi) => {
  const where = `block[${bi}] (${b.type}${b.headline ? `: "${String(b.headline).slice(0, 60)}"` : ''})`;
  if (!BLOCK_TYPES.has(b.type)) { err(`${where}: unknown block type`); return; }
  if (!Array.isArray(b.lines) || !b.lines.length) { err(`${where}: no lines`); return; }
  if (b.type === 'intro') { if (introSeen) err(`${where}: more than one intro`); introSeen = true; if (bi !== 0) err(`${where}: intro must be the first block`); }
  if (b.type === 'outro') { outroSeen = true; if (bi !== sc.blocks.length - 1) err(`${where}: outro must be the last block`); }

  // What this block is allowed to contain numbers from.
  let allowedDigits = dateDigits, ref = null;
  if (b.type === 'item') {
    ref = itemByHeadline.get(b.headline);
    if (!ref) err(`${where}: headline does not exactly match any item in ${path.basename(edPath)}`);
    else {
      if (b.section && b.section !== ref.section) err(`${where}: section "${b.section}" but the item is in "${ref.section}"`);
      if (seenItems.has(b.headline)) err(`${where}: item already has a block`);
      seenItems.add(b.headline); sectionsCovered.add(ref.section); itemBlocks++;
      allowedDigits = new Set([...digitsOf(itemText(ref.item)), ...dateDigits]);
    }
  } else if (b.type === 'intro') {
    allowedDigits = new Set([...summaryDigits, ...dateDigits]);
  }

  const blockText = b.lines.map((l) => l.text || '').join(' ');
  const lower = blockText.toLowerCase();

  b.lines.forEach((l, li) => {
    const lw = `${where} line[${li}]`;
    if (!hostKeys.includes(l.host)) err(`${lw}: host "${l.host}" is not one of ${hostKeys.join('/')}`);
    if (typeof l.text !== 'string' || l.text.trim().length < 2) err(`${lw}: empty text`);
    const text = String(l.text || '');
    lineCount++; words += text.trim().split(/\s+/).length;
    if (text.length > 600) err(`${lw}: line is ${text.length} chars (max 600) — split it`);
    if (/https?:\/\/|www\./i.test(text)) err(`${lw}: URLs must not be read aloud`);
    if (NUMBER_WORDS.test(text)) err(`${lw}: numbers must be written as digits, not words ("${text.match(NUMBER_WORDS)[0]}")`);
    const dbm = text.match(/\b\d{1,2}(?:st|nd|rd|th)?\s+(?:January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b/);
    if (dbm) err(`${lw}: dates are spoken month-first with an ordinal ("September 10th"), not "${dbm[0]}"`);
    // Numeric lock
    for (const raw of text.match(NUM_RE) || []) {
      const core = normNum(raw);
      if (!allowedDigits.has(core)) {
        if (b.type === 'transition' || b.type === 'outro') err(`${lw}: number "${raw}" — transitions and outros may not contain numbers`);
        else err(`${lw}: number "${raw}" does not appear in the ${b.type === 'intro' ? 'edition summary' : 'item'} — remove it or fix the item`);
      }
    }
    // Host alternation
    if (l.host === prevHost) { run++; if (run >= 4) err(`${lw}: ${l.host} has spoken ${run + 1} lines in a row (max 4)`); } else { prevHost = l.host; run = 0; }
  });

  // Banned language
  for (const w of bannedHits(blockText, BANNED)) err(`${where}: banned phrase "${w}" — no speculation or hype`);
  for (const w of WARN_WORDS) { const n = (lower.match(new RegExp(`\\b${w}\\b`, 'g')) || []).length; warnWordCount[w] = (warnWordCount[w] || 0) + n; }

  // Item-specific locks
  if (b.type === 'item' && ref) {
    const it = ref.item;
    // A source counts as named if its name (minus any parenthetical) or any slash/comma-separated part of it appears.
    const names = (it.sources || []).flatMap((s) => { const n = (s.name || '').replace(/\s*\(.*?\)\s*/g, ' ').trim().toLowerCase(); return [n, ...n.split(/\s*[/,]\s*/)]; }).filter((n) => n.length >= 3);
    if (names.length && !names.some((n) => lower.includes(n))) err(`${where}: must name a source (${(it.sources || []).map((s) => s.name).join(' / ')})`);
    for (const f of it.flags || []) {
      const phrases = CAVEAT_PHRASES[f] || [];
      if (!phrases.some((p) => lower.includes(p))) err(`${where}: item is flagged "${f}" — the hosts must say so (e.g. "${phrases[0]}")`);
    }
    const bulletsLower = (it.bullets || []).join(' ').toLowerCase();
    if (BULLET_CAVEAT_TRIGGERS.some((t) => bulletsLower.includes(t)) && !SCRIPT_CAVEAT_WORDS.some((w) => lower.includes(w))) {
      warn(`${where}: the item's bullets carry a caveat ("${BULLET_CAVEAT_TRIGGERS.find((t) => bulletsLower.includes(t))}") but the block does not voice one`);
    }
  }
  if (b.type === 'intro') {
    if (!/voiced by ai|synthetic voice|ai[- ]generated|ai voices|voices are ai|we(?:'re| are) ai|ai[- ]voiced|read by ai/i.test(blockText)) err(`${where}: intro must disclose that the episode is voiced by AI`);
    const o = dateObj(date), weekday = spokenDate(date).split(',')[0], alt = `${weekday} the ${ordinal(o.getUTCDate())} of ${spokenDate(date).split(', ')[1].split(' ')[0]}`;
    if (!blockText.includes(spokenDate(date)) && !blockText.includes(alt)) err(`${where}: intro must say the date the way it is spoken: "${spokenDate(date)}" or "${alt}"`);
    if (!blockText.includes(PODCAST.title)) err(`${where}: intro must name the show: "${PODCAST.title}"`);
    if (!blockText.includes(PODCAST.presenter)) err(`${where}: intro must say "presented by ${PODCAST.presenter}"`);
    for (const k of hostKeys) {
      const name = (hosts[k] || {}).name;
      if (!name) continue;
      const self = b.lines.some((l) => l.host === k && new RegExp(`\\b${name}\\b`).test(l.text || ''));
      if (!self) err(`${where}: host ${k} (${name}) must introduce themselves by name in the intro, in their own line`);
    }
  }
  if (b.type === 'outro' && !/\btomorrow\b/i.test(blockText)) err(`${where}: outro must remind listeners to listen in tomorrow`);
});

// ---------- whole-script locks ----------
{
  const all = (sc.blocks || []).flatMap((b) => (b.lines || []).map((l) => l.text || '')).join(' ');
  const mentions = (all.match(new RegExp(PODCAST.presenter, 'g')) || []).length;
  if (mentions > 1) err(`"${PODCAST.presenter}" is mentioned ${mentions} times — once, in the intro, is the limit (no plugging)`);
}
if (!introSeen) err('no intro block');
if (!outroSeen) err('no outro block');
for (const sec of ed.sections) if (!sectionsCovered.has(sec.name)) err(`section "${sec.name}" has no item block — every section must be represented`);
const totalItems = ed.sections.reduce((n, s) => n + s.items.length, 0);
const minItems = Math.min(8, totalItems);
if (itemBlocks < minItems) err(`only ${itemBlocks} item blocks; need at least ${minItems}`);
const [minW, maxW] = [1300, 2300];
if (words < minW || words > maxW) err(`script is ${words} words; must be ${minW}–${maxW}`);
for (const [w, n] of Object.entries(warnWordCount)) if (n > 3) warn(`"${w}" used ${n} times — keep it factual`);

for (const w of warnings) console.log(`WARN  ${w}`);
for (const e of errors) console.log(`ERROR ${e}`);
console.log(`${file}: ${sc.blocks ? sc.blocks.length : 0} blocks, ${itemBlocks} items voiced, ${lineCount} lines, ${words} words (~${Math.round(words / 150)} min) — ${errors.length} error(s), ${warnings.length} warning(s)`);
process.exit(errors.length ? 1 : 0);

